from itertools import permutations

def langford_sequence(n, k):
    for p in permutations(range(1, n+1)):
        seq = [0]*(2*n)
        for i, x in enumerate(p):
            seq[2*i] = x
            seq[2*i + x + 1] = x
        if len(set(seq)) == n and all(x > 0 for x in seq):
            return seq
    return "UNSATISFIABLE"

